        "[workspace]\nmembers = [\"crates/source\", \"packages/app\"]\nresolver = \"2\"\n",
    )
    .unwrap();
    fs::create_dir_all(root.join("crates/source/src")).unwrap();
    fs::write(
        root.join("crates/source/Cargo.toml"),
        "[package]\nname = \"source\"\nversion = \"1.0.0\"\nedition = \"2021\"\n",
    )
