   138	/// Renders `state`, then reapplies `existing`'s on-disk formatting (BOM, CRLF vs LF, indent width) instead of the
   139	/// default 2-space bare-LF shape, so a CRLF or custom-indent `pre.json` (e.g. `core.autocrlf=true`, or hand-edited)
   140	/// is not reformatted on a `pre exit` or mid-cycle `version` rewrite.
   141	pub fn write_pre_json_preserving(state: &PreState, existing: &str) -> String {
   142	    let fp = PreJsonFingerprint::detect(existing);
   143	    let rendered = render_pre_json(state, &fp.indent_str());
   144	    fp.apply(&rendered)
   145	}
   146	
   147	fn render_pre_json(state: &PreState, indent_str: &str) -> String {
   148	    let mut map = IndexMap::new();
   149	    map.insert("mode".to_string(), serde_json::to_value(state.mode).unwrap());
   150	    map.insert("tag".to_string(), serde_json::to_value(&state.tag).unwrap());
   151	
   152	    let mut init_map = IndexMap::new();
   153	    for (pkg, ver) in &state.initial_versions {
   154	        init_map.insert(pkg.clone(), serde_json::to_value(ver).unwrap());
   155	    }
   156	    map.insert("initialVersions".to_string(), serde_json::to_value(init_map).unwrap());
   157	    map.insert(
   158	        "changesets".to_string(),
   159	        serde_json::to_value(&state.changesets).unwrap(),
   160	    );
   161	
   162	    let formatter = serde_json::ser::PrettyFormatter::with_indent(indent_str.as_bytes());
   163	    let mut buf = Vec::new();
   164	    let mut serializer = serde_json::Serializer::with_formatter(&mut buf, formatter);
   165	    serde::Serialize::serialize(&map, &mut serializer).unwrap();
   166	    let mut out = String::from_utf8(buf).unwrap();
   167	    out.push('\n');
   168	    out
   169	}
