   171	/// Byte-level formatting facts (BOM, CRLF, indent) `pre.json` must preserve across a rewrite.
   172	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
   173	struct PreJsonFingerprint {
   174	    has_bom: bool,
   175	    crlf: bool,
   176	    indent: PreJsonIndent,
   177	}
   178	
   179	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
   180	enum PreJsonIndent {
   181	    Spaces(u8),
   182	    Tabs,
   183	}
   184	
   185	impl PreJsonFingerprint {
   186	    fn detect(content: &str) -> Self {
   187	        let has_bom = content.starts_with('\u{FEFF}');
   188	        let clean = content.strip_prefix('\u{FEFF}').unwrap_or(content);
   189	        let crlf = clean.contains("\r\n");
   190	
   191	        // The first quote-leading line is a top-level key at indent depth 1; its leading whitespace is one unit.
   192	        let mut indent = PreJsonIndent::Spaces(2);
   193	        for line in clean.lines() {
   194	            let trimmed = line.trim_start();
   195	            if trimmed.starts_with('"') && line.len() > trimmed.len() {
   196	                let leading = &line[..line.len() - trimmed.len()];
   197	                indent = if leading.contains('\t') {
   198	                    PreJsonIndent::Tabs
   199	                } else {
   200	                    PreJsonIndent::Spaces(leading.len() as u8)
   201	                };
   202	                break;
   203	            }
   204	        }
   205	
   206	        PreJsonFingerprint { has_bom, crlf, indent }
   207	    }
   208	
   209	    fn indent_str(&self) -> String {
   210	        match self.indent {
   211	            PreJsonIndent::Tabs => "\t".to_string(),
   212	            PreJsonIndent::Spaces(n) => " ".repeat(n as usize),
   213	        }
   214	    }
   215	
   216	    /// Reapplies this fingerprint to `rendered`, a freshly-serialized body with bare-LF endings and no BOM.
   217	    fn apply(&self, rendered: &str) -> String {
   218	        let mut out = if self.crlf {
   219	            rendered.replace("\r\n", "\n").replace('\n', "\r\n")
   220	        } else {
   221	            rendered.to_string()
   222	        };
   223	        if self.has_bom {
   224	            out = format!("\u{FEFF}{out}");
   225	        }
   226	        out
   227	    }
   228	}
